// Inspired by randØ - Polar Mystery
// https://twitter.com/rand0mograph/status/1595175999699881986
var agentsNum = 200;
var range = 640;

setup = () => {
  createCanvas(640, 640, WEBGL);
  Agents.init();
};

draw = () => {
  background("white");
  rotateX(1);
  rotateZ(frameCount * 0.01);
  Agents.addAgents();
  Agents.updateAgents();
  Agents.render();
};

var agent = () => ({
  angle: random(TWO_PI),
  distance: 0,
  x: 0,
  y: 0,
});

var Agents = {
  agents: [],

  init() {
    this.agents.length = 0;
  },
  addAgents() {
    if (this.agents.length < agentsNum) {
      this.agents.push(agent());
    }
  },
  updateAgents() {
    for (const a of this.agents) {
      a.distance += 2;
      a.x = cos(a.angle) * a.distance;
      a.y = sin(a.angle) * a.distance;
    }
    this.agents = this.agents.filter((a) => a.distance < width);
  },
  render() {
    translate(0, 0, 50);

    for (let i = this.agents.length; i--; ) {
      const current = this.agents[i];
      for (let j = i; j--; ) {
        const other = this.agents[j];
        const dis2 = (current.x - other.x) ** 2 + (current.y - other.y) ** 2;

        if (
          !this.agents.some(
            (any) =>
              dis2 > (any.x - current.x) ** 2 + (any.y - current.y) ** 2 &&
              dis2 > (any.x - other.x) ** 2 + (any.y - other.y) ** 2
          )
        ) {
          const ave = (current.distance + other.distance) / 2;
          const z = 1.017 ** (width / 2 - ave);
          const s = ave / 8;
          stroke(map(ave, 0, range, 0, 255));
          push();
          translate(
            (current.x + other.x) / 2,
            (current.y + other.y) / 2,
            z / 2
          );
          const r = atan2(current.y - other.y, current.x - other.x);
          rotate(r);
          dis3 = (current.x - other.x) ** 2 + (current.y - other.y) ** 2;
          box(dis3 ** 0.5, 2, z);
          pop();
        }
      }
    }

    for (const a of this.agents) {
      const z = 1.017 ** (width / 2 - a.distance);
      const s = a.distance / 8;
      stroke(map(a.distance, 0, range, 0, 255));
      push();
      translate(a.x, a.y, z / 2);
      rotate(a.angle);
      box(s / 2, s / 2, z / 2);
      pop();
    }
  },
};
